/* 流利蓝 · 暗色（Fluent Dark, layer 2）—— 与亮色那枚同一条组件层，只换旋钮
 *
 * 这一份与 `fluent-blue/components.css` 的关系是**受测的**：除下面这块 `:root` 之外，
 * 两个文件逐字节相同（`marketContent.test.ts` 钉着）。为什么钉得住：这一层的颜色本来就
 * 全部派生自 token（四档表面、--text、--accent），亮暗的差别不在"哪条规则"，而在
 * "混合方向"与"阴影浓度"这两类旋钮值上——
 *  · 按压态：亮色往 var(--text)（深墨）混＝变暗；暗色的 var(--text) 是白，照抄就会**越按越亮**，
 *    所以这里显式往 #000000 混。
 *  · 阴影：黑色半透明影在 #323232 面板上几乎看不出来，暗色要提到 3~4 倍浓度才读得出"浮起"。
 *  · 卡片描边：白 9% 的头发丝线在暗色上偏淡，提到 12%。
 * 真要往规则体里加分支，就得同时往另一枚加，或者把差异也做成旋钮——不许出现两份平行清单。
 *
 * 四条自我约束照亮色那枚原文（颜色一律走 var()、动效只写在单类选择器上、
 * 不写 position:fixed 与 z-index、只碰真实存在的类名），逐条对应 theme_audit 的一格。
 */
:root {
  /* 本包内部用的旋钮。只定义新键、不碰白名单（白名单归 theme_patch / vars 那块）。 */
  --fb-fill-secondary: color-mix(in srgb, var(--text) 5%, var(--bg-panel));
  --fb-fill-hover: color-mix(in srgb, var(--text) 8%, var(--bg-panel));
  --fb-fill-pressed: color-mix(in srgb, var(--text) 4%, var(--bg-panel));
  --fb-accent-hover: color-mix(in srgb, var(--accent) 88%, #ffffff);
  --fb-accent-pressed: color-mix(in srgb, var(--accent) 84%, #000000);
  --fb-card-line: color-mix(in srgb, var(--text) 12%, transparent);
  --fb-acrylic: color-mix(in srgb, var(--bg-panel) 90%, transparent);
  /* P131-C 资产通道：Fluent 的亚克力不是"半透明"就完了，还要有一层细噪声。
     这一贴从主题的 assets 里来（`--fx-asset-acrylic-noise`），没带资产的那枚解析成空
     ⇒ 同一份规则体，有材质就贴、没材质就不贴，不靠两份 CSS 各写一遍。 */
  --fb-noise: var(--fx-asset-acrylic-noise, none);
  --fb-shadow-pop: 0 2px 4px rgba(0, 0, 0, 0.3), 0 8px 20px rgba(0, 0, 0, 0.45);
  --fb-shadow-card: 0 1px 2px rgba(0, 0, 0, 0.45);
  --fb-duration: var(--dur-fast);
}

/* ---------- 外壳：两条标题栏 / 信息栏 / 活动导轨 ---------- */

/* Fluent 的标题栏不是"涂深的"，是"退到壳档 + 一条极轻的下边线"。 */
.ibar {
  border-bottom: 1px solid var(--border-soft);
}

.tbar {
  border-bottom: 1px solid var(--border-soft);
}

/* 窗口三键：Fluent 要的是"方角、铺满整行高、hover 才上色"，与本仓那套圆角图标键不同。 */
.tb-btn {
  border-radius: var(--radius-s);
  color: var(--text-dim);
  transition: background-color var(--fb-duration) var(--ease), color var(--fb-duration) var(--ease);
}

.tb-btn:hover {
  background: var(--fb-fill-hover);
  color: var(--text);
}

.tb-btn:active {
  background: var(--fb-fill-pressed);
  color: var(--text-dim);
}

/* 关闭键是 Windows 的约定色，不是 Fluent 本家色，所以写死（见文件头第 1 条）。 */
.tb-close:hover {
  background: #e81123;
  color: #ffffff;
  border-radius: var(--radius-s);
}

.tb-close:active {
  background: #c42b1c;
  color: #ffffff;
}

.statusbar {
  border-top: 1px solid var(--border-soft);
}

/* 活动导轨：选中项 = 淡底 + 左侧一枚强调色小胶囊（Fluent NavigationView 的形状）。
   胶囊用 ::before 画，不用"单侧粗边框"——那条是本仓明令避免的装饰手法，且会虚增边框读数。 */
.rail2-btn {
  position: relative;
  color: var(--text-dim);
  transition: background-color var(--fb-duration) var(--ease), color var(--fb-duration) var(--ease);
}

.rail2-btn:hover {
  background: var(--fb-fill-secondary);
  color: var(--text);
}

.rail2-btn.on {
  background: var(--accent-soft);
  color: var(--accent);
}

.rail2-btn.on::before {
  content: "";
  position: absolute;
  left: 2px;
  top: 50%;
  width: 3px;
  height: 16px;
  margin-top: -8px;
  border-radius: var(--radius-pill);
  background: var(--accent);
}

/* ---------- 按钮族 ---------- */

/* Fluent 标准按钮：白底 + 一圈很轻的描边 + 底部那道略重的边（"厚度"）。
   本仓 --ctl-h-2 是 26px，Fluent 是 32px——这里不追：追高会把 700px 宽的面板工具条顶穿（P117-C 刚治平）。 */
.btn {
  background: var(--bg-panel);
  border-color: var(--border);
  border-bottom-color: var(--line-strong);
  color: var(--text);
  box-shadow: none;
  transition: background-color var(--fb-duration) var(--ease), border-color var(--fb-duration) var(--ease), color var(--fb-duration) var(--ease);
}

.btn:hover {
  background: var(--fb-fill-hover);
  border-color: var(--line-strong);
}

.btn:active {
  background: var(--fb-fill-pressed);
  border-color: var(--border);
  color: var(--text-dim);
  transform: scale(0.98);
}

.btn:disabled,
.btn[disabled] {
  background: var(--fb-fill-secondary);
  border-color: var(--border-soft);
  color: color-mix(in srgb, var(--text-dim) 60%, var(--bg-panel));
  transform: none;
}

.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

.btn.primary:hover {
  background: var(--fb-accent-hover);
  border-color: var(--fb-accent-hover);
}

.btn.primary:active {
  background: var(--fb-accent-pressed);
  border-color: var(--fb-accent-pressed);
  color: var(--on-accent);
}

.btn.primary:disabled {
  background: color-mix(in srgb, var(--accent) 38%, var(--bg-panel));
  border-color: transparent;
  color: color-mix(in srgb, var(--on-accent) 72%, transparent);
}

/* 图标键：Fluent 的图标按钮是"方一点、hover 才有底"，不常驻描边。 */
.icon-btn {
  border-color: transparent;
  border-bottom-color: transparent;
  background: transparent;
}

.icon-btn:hover {
  background: var(--fb-fill-hover);
  border-color: var(--border-soft);
}

.icon-btn:active {
  background: var(--fb-fill-pressed);
  transform: scale(0.94);
}

/* 焦点：Fluent 的 focus rect 是"外实内留白"。留白就是 outline-offset——
   这一条在 P130 那份文档里被列为"主题层够不到的能力"，在这一层它写得出。 */
.btn:focus-visible,
.icon-btn:focus-visible,
.input:focus-visible,
.qk-chip:focus-visible,
.rail2-btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* ---------- 输入族 ---------- */

.input {
  background: var(--bg-panel);
  border-color: var(--border);
  border-bottom-color: var(--line-strong);
  box-shadow: none;
  transition: border-color var(--fb-duration) var(--ease), background-color var(--fb-duration) var(--ease);
}

.input:hover {
  border-bottom-color: var(--text);
}

.input:focus {
  background: var(--bg-panel);
  border-bottom-color: var(--accent);
  border-bottom-width: 2px;
}

.input:disabled,
.input[readonly] {
  background: var(--fb-fill-secondary);
  border-bottom-color: var(--border);
  color: var(--text-dim);
}

select.input {
  background: var(--bg-panel);
}

/* 数字步进（控制画布卡片上的 ▲▼）：Fluent 把它当"贴着输入框的一组小键"。 */
.ctl-step {
  background: var(--bg-panel);
  border-color: var(--border);
}

.ctl-step:focus-within {
  border-bottom-color: var(--accent);
  border-bottom-width: 2px;
}

/* 勾选与单选：Fluent 的方框在"未选"时是描边为主、底色很淡，选中才填满强调色。
   accent-color 已经管住了原生态，这里只补容器。 */
.chk {
  color: var(--text);
}

.chk:hover .chk-box,
.chk:hover input[type="checkbox"] {
  border-color: var(--accent);
}

/* 开关：本仓是 label 包 input 的自绘形状。轨道用凹档、滑块用白、开=强调色。 */
.set-switch {
  background: var(--bg-inset);
  border-color: var(--line-strong);
  transition: background-color var(--dur-base) var(--ease), border-color var(--dur-base) var(--ease);
}

.set-switch input:checked + * ,
.set-switch.on {
  background: var(--accent);
  border-color: var(--accent);
}

/* 滑杆：轨道两段（已走/未走）都归强调色家族，拇指白底描边。
   伪元素 ::-webkit-slider-* 的特异性按伪元素计（(0,1,1) 不高于基线），动效写在这里安全。 */
.ctl-slider {
  background: transparent;
}

.ctl-slider::-webkit-slider-runnable-track {
  background: color-mix(in srgb, var(--accent) 26%, var(--bg-inset));
  border-radius: var(--radius-pill);
}

.ctl-slider::-webkit-slider-thumb {
  background: var(--bg-panel);
  border: 1px solid var(--line-strong);
  box-shadow: var(--fb-shadow-pop);
}

.ctl-slider:hover::-webkit-slider-thumb {
  border-color: var(--accent);
}

.ctl-slider:disabled::-webkit-slider-thumb {
  background: var(--fb-fill-secondary);
  border-color: var(--border-soft);
}

/* ---------- 页签（dockview 公共类，只用公开形状） ---------- */

/* 页签条：Fluent 的标签栏是"内容往上抬"，所以条本身退到凹档、选中的那枚升到面板档。 */
.dv-tabs-and-actions-container {
  background: var(--bg-inset);
}

.dv-tab {
  border-radius: var(--radius-m) var(--radius-m) 0 0;
  color: var(--text-dim);
  transition: background-color var(--fb-duration) var(--ease), color var(--fb-duration) var(--ease);
}

.dv-tab:hover {
  background: var(--fb-fill-hover);
  color: var(--text);
}

.dv-tab.dv-active-tab {
  background: var(--bg-panel);
  color: var(--text);
  box-shadow: inset 0 2px 0 0 var(--accent);
}

.dv-default-tab {
  color: inherit;
}

.dv-default-tab-content {
  color: inherit;
}

/* 页签上的那颗关闭叉：13px 是可见尺寸，命中区靠内边距撑（P105-B 的结论，别再改回 15）。 */
.dv-default-tab-action {
  border-radius: var(--radius-s);
  color: var(--text-dim);
}

.dv-default-tab-action:hover {
  background: var(--fb-fill-hover);
  color: var(--text);
}

/* 分隔条：可见很细、热区靠 ::before 放宽（与本仓 B13 同一条手法）。 */
.dv-sash {
  background: var(--border-soft);
  transition: background-color var(--fb-duration) var(--ease);
}

.dv-sash:hover {
  background: var(--accent);
}

/* ---------- 浮层：菜单 / 命令面板 / 气泡 ---------- */

/* Fluent 的弹出层是"8px 圆角 + 分层影 + 半透明底"。
   **半透明留、`backdrop-filter: blur()` 不留**——这是量出来的，不是审美：
   带着 blur 时，无头渲染（--disable-gpu）下任何一次全树 `getComputedStyle` 扫描
   （`theme_audit` 就是这种扫描）40 秒都不返回；去掉 blur 后同一台机器同一屏秒回。
   也就是说：亚克力不是"更好看"，是"每次重算都要重合成一遍"。
   真 acrylic 的正确位置是 P131-E（Rust 侧窗口效果，由合成器做），不是主题 CSS。 */
.ctx-menu,
.sb-menu,
.aiw-menu,
.cmdk {
  background: var(--fb-acrylic);
  background-image: var(--fb-noise);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-l);
  box-shadow: var(--fb-shadow-pop);
}

/* 四族"可点的行"：右键菜单项 / 信息栏计数键 / 挂件菜单项 / 命令面板行。
   类名是照宿主改对的——原先写的 `.sb-item`、`.aiw-item`、`.cmdk-row` 宿主里根本没有，
   那三条一直在画空气（新门 J3 抓出来的，见 docs 的 P132-A2 一节）。 */
.ctx-item,
.ib-count,
.aiw-menu-item,
.cmdk-item {
  border-radius: var(--radius-s);
  color: var(--text);
  transition: background-color var(--dur-snap) var(--ease);
}

.ctx-item:hover,
.ib-count:hover,
.aiw-menu-item:hover,
.cmdk-item:hover,
.ctx-item:focus,
.ib-count:focus,
.aiw-menu-item:focus,
.cmdk-item.sel {
  background: var(--fb-fill-hover);
}

/* 禁用态宿主有两写法：按钮走 `:disabled`，挂件菜单是 `.disabled` 类 ⇒ 两边都得给 */
.ctx-item:disabled,
.ib-count:disabled,
.cmdk-item:disabled {
  color: color-mix(in srgb, var(--text-dim) 62%, var(--bg-panel));
  background: transparent;
}

.aiw-menu-item.disabled,
.aiw-menu-item.disabled:hover {
  background: transparent;
}

.cmdk-input {
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--border-soft);
  border-radius: 0;
  color: var(--text);
}

.cmdk-empty {
  color: var(--text-dim);
}

.help-bubble {
  background: var(--fb-acrylic);
  background-image: var(--fb-noise);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-l);
  box-shadow: var(--fb-shadow-pop);
  color: var(--text);
}

/* 提示条：本仓的 .ai-toast 已经用 inset 描边当"厚度"，这里只把它抬到 Fluent 的弹层影。 */
.ai-toast {
  box-shadow: inset 0 0 0 1px var(--border-soft), var(--fb-shadow-pop);
}

/* ---------- 对话框 ---------- */

.modal-mask {
  background: color-mix(in srgb, var(--text) 34%, transparent);
}

.modal {
  background: var(--bg-panel);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-xl);
  box-shadow: var(--fb-shadow-pop);
}

.modal-title {
  color: var(--text);
  font-weight: 600;
}

.modal-foot {
  border-top: 1px solid var(--border-soft);
}

/* ---------- 卡片与列表行 ---------- */

/* Fluent 的卡片靠"极轻的描边 + 很浅的影"分层，hover 才加一档影——不上浮（上浮是动效，
   而 hover 位移会把整屏的滚动条算进重排，代价与收益不成比例）。 */
.ctl-card,
.theme-card,
.set-card,
.props-item {
  background: var(--bg-panel);
  border: 1px solid var(--fb-card-line);
  border-radius: var(--radius-l);
  box-shadow: var(--fb-shadow-card);
  transition: border-color var(--fb-duration) var(--ease), box-shadow var(--fb-duration) var(--ease);
}

.ctl-card:hover,
.theme-card:hover,
.set-card:hover,
.props-item:hover {
  border-color: var(--border);
  box-shadow: var(--fb-shadow-pop);
}

.theme-card.on {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
}

.tpl-row,
.cmd-item {
  border-radius: var(--radius-m);
  color: var(--text);
  transition: background-color var(--dur-snap) var(--ease);
}

.tpl-row:hover,
.cmd-item:hover {
  background: var(--fb-fill-secondary);
}

.tpl-row.on,
.cmd-item.on {
  background: var(--accent-soft);
  color: var(--accent);
}

/* ---------- 属性页与提示层级 ---------- */

.props-title {
  color: var(--text);
  font-weight: 600;
}

.props-section {
  border-top: 1px solid var(--border-soft);
}

.props-hint {
  color: var(--text-dim);
}

.form-hint {
  color: var(--text-dim);
}

.set-group-title {
  color: var(--text-dim);
  font-weight: 600;
  letter-spacing: 0.2px;
}

/* ---------- 芯片 / 胶囊 / 计数徽标 ---------- */

.qk-chip {
  background: var(--bg-panel);
  border: 1px solid var(--fb-card-line);
  color: var(--text);
  transition: background-color var(--fb-duration) var(--ease), border-color var(--fb-duration) var(--ease);
}

.qk-chip:hover {
  background: var(--fb-fill-hover);
  border-color: var(--border);
}

.qk-chip.on {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

.cb-capsule {
  background: var(--fb-fill-secondary);
  border: 1px solid var(--fb-card-line);
  color: var(--text-dim);
}

.ib-count {
  background: var(--accent-soft);
  color: var(--accent);
  border-radius: var(--radius-pill);
}

/* 面板工具条上那排小键（帧画布 / 组帧台共用形状） */
.pca-btn {
  border-radius: var(--radius-m);
  color: var(--text-dim);
  transition: background-color var(--fb-duration) var(--ease), color var(--fb-duration) var(--ease);
}

.pca-btn:hover {
  background: var(--fb-fill-hover);
  color: var(--text);
}

.pca-btn.on {
  background: var(--accent-soft);
  color: var(--accent);
}

.pca-btn:disabled {
  color: color-mix(in srgb, var(--text-dim) 55%, var(--bg-panel));
  background: transparent;
}

/* ---------- AI 对话面 ---------- */

.ai-msg {
  border-radius: var(--radius-l);
}

.ai-msg code,
.ai-msg pre {
  background: var(--bg-inset);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-s);
}

/* ---------- 表格 ---------- */

.tbl-filter {
  background: var(--bg-panel);
}

.tbl-col-del {
  border-radius: var(--radius-s);
  color: var(--text-dim);
}

.tbl-col-del:hover {
  background: color-mix(in srgb, var(--danger) 12%, var(--bg-panel));
  color: var(--danger);
}

/* ---------- 减弱动效的兜底自检 ----------
   上面所有 transition 都写在单类选择器上（(0,1,0) < 宿主的 html.no-motion * (0,1,1)），
   所以宿主那条一开，这里全部失效——不需要在本文件里再抄一份 no-motion 分支。
   `theme_audit` 的 motionOverride 一格就是这条的守卫：它若报出任何一条，就说明
   有人把动效写到了两级类上，用户设的"减少动效"会被这套主题压住。 */
